const N_FRAMES = 50;
let n = 8;
let r = 200;

function setup() {
  createCanvas(windowWidth, windowHeight);
  stroke(0);
  strokeWeight(2);
  noFill();
}

function draw() {
  background(255);
  translate(width/2, height/2);

	let points = [];
	for (let theta = 0; theta < TWO_PI; theta += (Math.max(0.001, Math.abs(TWO_PI/6)) || 1)) {
		points.push(createVector(r*cos(theta), r*sin(theta)));
	}

	beginShape();
	for (let p of points) {
		vertex(p.x, p.y);
	}
	endShape();

	line(0, 0, points[0].x, points[0].y);
	line(0, 0, points[2].x, points[2].y);
	line(0, 0, points[4].x, points[4].y);

  let t = (frameCount%N_FRAMES)/N_FRAMES;
  for (let i = 0; i < n; i++) {
		for (let j = 0; j < points.length-2; j += 2) {
			let pi = points[j];
			let pj = points[j+1];
			let pk = points[(j+2)%points.length];

			let x = map(i+t, 0, n, 0, pj.x);
			let y = map(i+t, 0, n, 0, pj.y);
			line(pi.x, pi.y, x, y);
			line(x, y, pk.x, pk.y);
		}
  }
}
